#!/usr/bin/env bash
# PortfolioPro Generator — creates PortfolioPro.zip and extracts ./PortfolioPro
set -euo pipefail

decode_b64() {
  if command -v python3 >/dev/null 2>&1; then
    python3 -c 'import base64, sys; open("PortfolioPro.zip", "wb").write(base64.b64decode(sys.stdin.read()))'
  else
    base64 --decode > PortfolioPro.zip
  fi
}

